function parseCents(value) {
  if (typeof value !== "string") return null;

  const match = value.trim().match(/^([0-9]+)(?:\.([0-9]{1,2}))?$/);
  if (!match) return null;

  const cents = BigInt(match[1]) * 100n
    + BigInt((match[2] || "").padEnd(2, "0"));

  return cents > BigInt(Number.MAX_SAFE_INTEGER) ? null : Number(cents);
}

function uniqueById(items) {
  const seen = new Set();
  const result = [];

  for (const item of items) {
    if (!seen.has(item.id)) {
      seen.add(item.id);
      result.push(item);
    }
  }

  return result;
}

function mergeIntervals(intervals) {
  const sorted = intervals
    .map(([start, end]) => [start, end])
    .sort((a, b) => {
      if (a[0] < b[0]) return -1;
      if (a[0] > b[0]) return 1;
      if (a[1] < b[1]) return -1;
      if (a[1] > b[1]) return 1;
      return 0;
    });

  const merged = [];

  for (const [start, end] of sorted) {
    if (merged.length === 0 || start > merged[merged.length - 1][1]) {
      merged.push([start, end]);
    } else if (end > merged[merged.length - 1][1]) {
      const last = merged[merged.length - 1];
      merged[merged.length - 1] = [last[0], end];
    }
  }

  return merged;
}
